WITH base AS (SELECT * FROM suppliers WHERE supplier_name IS NOT NULL AND (city IN ('Berlin', 'Tokyo') OR country = 'JP')), Agg AS (SELECT CASE WHEN rating >= 3.8 THEN 'high' WHEN rating >= 1.8 THEN 'mid' ELSE 'low' END AS rating_bucket, country, SUM(rating) AS total_rating, COUNT(rating) AS rating_count FROM base GROUP BY CASE WHEN rating >= 3.8 THEN 'high' WHEN rating >= 1.8 THEN 'mid' ELSE 'low' END, country) SELECT rating_bucket, country, total_rating, rating_count FROM Agg
